 function canEdit(kind,row){if(!write||row.DELETED)return false;if(['users','bom','audit','stock'].includes(kind))return admin;if(['shipments','receipts'].includes(kind)&&kind==='shipments')return admin;if(kind==='documents'&&row.STATUS==='POSTED')return admin;if(kind==='production'&&(row.STATUS==='COMPLETED'||row.MATERIALS_ISSUED))return admin;return true;}
