 async function open(kind,row){
  E('');NewPart(null);B(true);try{
   let record=row?await api(kind+'/'+row.ID):null;
   if(kind==='parts')F({...refs,models:await api('models')});
   if(['documents','bom','production','vehicles','shipments','receipts'].includes(kind)){
    const names=['parts','suppliers','models','bom','vehicles','stock','dealers','carriers'];const data=await Promise.all(names.map(n=>n==='bom'&&session.account_kind==='STORE'?Promise.resolve([]):api(n)));const lookup=Object.fromEntries(names.map((n,i)=>[n,data[i]]));
    // Retain historical selections even when a referenced catalog has been archived.
    if(record&&kind==='documents'&&record.SUPPLIER_ID&&!lookup.suppliers.some(x=>x.ID===record.SUPPLIER_ID))lookup.suppliers.push({ID:record.SUPPLIER_ID,NAME:row.SUPPLIER||'Nhà cung cấp cũ'});
    if(record&&kind==='production')for(const line of record.lines||[])if(!lookup.bom.some(b=>b.ID===line.BOM_ID))lookup.bom.push({ID:line.BOM_ID,MODEL:line.MODEL||'Mẫu xe cũ',VERSION:'cũ'});
    if(record&&kind==='production'&&!lookup.bom.some(x=>x.ID===record.BOM_ID))lookup.bom.push({ID:record.BOM_ID,MODEL:'Định mức của lệnh cũ'});
    if(record&&kind==='vehicles'&&!lookup.models.some(x=>x.ID===record.MODEL_ID))lookup.models.push({ID:record.MODEL_ID,NAME:row.MODEL||'Mẫu xe cũ'});
    F(lookup);
   }
   const f=record?toForm(record):{};if(kind==='parts'&&record?.COLOR_PARENT_ID)f.code=row.CODE;if(kind==='documents'){f.type=f.type||'IN';f.sales_purpose=f.sales_purpose||'INTERNAL';f.sale_date=String(f.sale_date||localDate()).slice(0,10);}if(['shipments','documents'].includes(kind)){f.sale_channel=f.sale_channel||'STORE';f.discount=f.discount||0;f.support=f.support||0;f.transport_cost=record?(record.CARRIER_COST_KNOWN===false?'':f.transport_cost??''):'';f.transport_fee=f.transport_fee||0;}if(['vehicles','receipts','shipments'].includes(kind))f.vehicle_type=f.vehicle_type||'REGISTERED';if(kind==='shipments'){f.shipment_purpose=f.shipment_purpose||'SALE';f.shipment_date=String(f.shipment_date||localDate()).slice(0,10);f.accessories=f.accessories??'';f.vehicle_details=Object.fromEntries((record?.vehicles||[]).map(v=>[v.ID,{requested_quantity:v.REQUESTED_QUANTITY||1,unit_price:v.UNIT_PRICE??''}]));}
   if(kind==='shipments')f.chargers=(record?.chargers||[]).map(toForm);
   if(kind==='shipments')f.ids=(record?.vehicles||[]).map(v=>v.ID);
   if(kind==='stock')f.quantity=record.QUANTITY;
   V(f);L(kind==='production'?(record?.lines?.map(toForm)||[{bom_id:'',quantity:1,color:''}]):kind==='receipts'?[]:record?.lines?record.lines.map(toForm):[{part_id:'',quantity:1,unit_cost:''}]);M({kind,row:record,edit:!!row});
  }catch(e){E(e.message)}finally{B(false)}
 }
