 async function detail(kind,row){B(true);E('');try{const r=await api(kind+'/'+row.ID);if(['bom','documents'].includes(kind)&&r.lines){const parts=await api('parts');r.lines=r.lines.map(l=>({...l,PART_NAME:parts.find(p=>p.ID===l.PART_ID)?.NAME||'—',PART_COLOR:parts.find(p=>p.ID===l.PART_ID)?.COLOR||'—'}));}M({kind:'detail',entity:kind,record:r})}catch(e){E(e.message)}finally{B(false)}}
 function input(key,title,type='text',options={}){
  const optional=['phone','address','note','minimum','accessories','delivery_person','recipient','warehouse_keeper','party_code','province','discount','support','transport_cost','transport_fee','carrier_name','carrier_phone','average_unit_cost'].includes(key)||(key==='reason'&&modal?.kind==='shipments')||(key==='password'&&modal?.edit)||(key==='purchase_unit_cost'&&modal?.edit);
  return <label>{title}{type==='material-group'?<select aria-label={title} value={form[key]||'UNASSIGNED'} onChange={e=>V({...form,[key]:e.target.value})}><option value="UNASSIGNED">Chưa phân nhóm</option>{materialGroups.map(([id,label])=><option key={id} value={id}>{label}</option>)}</select>:type==='date'?<VietnameseDatePicker label={title} value={form[key]||''} onChange={value=>V({...form,[key]:value})}/>:type==='account-kind'?<select aria-label={title} required value={form[key]==='UNSET'?'':form[key]||session?.account_kind||''} onChange={e=>V({...form,[key]:e.target.value})}><option value="">Chọn loại tài khoản</option><option value="FACTORY">Nhà máy</option><option value="STORE">Cửa hàng</option></select>:type==='role'?<select aria-label={title} required value={form[key]||'WAREHOUSE'} disabled={options.disabled} onChange={e=>V({...form,[key]:e.target.value})}><option value="WAREHOUSE">Thủ kho</option><option value="VIEWER">Chỉ xem</option><option value="ADMIN">Quản trị</option></select>:<span className={type==='password'?'password-field':''}>{['purchase_unit_cost','average_unit_cost','discount','support','transport_cost','transport_fee'].includes(key)?<MoneyInput aria-label={title} required={options.required??!optional} decimals={key==='average_unit_cost'?6:2} value={form[key]??''} disabled={options.disabled} onChange={e=>V({...form,[key]:e.target.value})}/>:<input aria-label={title} required={options.required??!optional} type={type==='password'&&eyes[key]?'text':type} min="0" step={key==='average_unit_cost'?'0.000001':['purchase_unit_cost','discount','support','transport_cost','transport_fee'].includes(key)?'0.01':'0.001'} maxLength={type==='number'?undefined:500} value={form[key]??''} disabled={options.disabled} onChange={e=>V({...form,[key]:e.target.value})}/>} {type==='password'&&<button type="button" className="eye" aria-label={eyes[key]?'Ẩn '+title:'Hiện '+title} aria-pressed={!!eyes[key]} onClick={()=>Eye({...eyes,[key]:!eyes[key]})}><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>{eyes[key]&&<path d="M3 3l18 18"/>}</svg></button>}</span>}</label>;
 }

 function pricedLine(line){
  if(form.type!=='IN')return line;
  let part=refs.parts.find(p=>String(p.ID)===String(line.part_id));
  if(part&&!part.COLOR_PARENT_ID&&part.COLOR_MODELS?.includes(Number(line.color_model_id))){
   const normalize=s=>String(s||'').normalize('NFC').trim().toLowerCase().replace(/[\s-]+/g,' ');
   part=refs.parts.find(p=>String(p.COLOR_PARENT_ID)===String(line.part_id)&&String(p.COLOR_MODEL_ID)===String(line.color_model_id)&&normalize(p.COLOR)===normalize(line.color));
  }
  return {...line,unit_cost:part?.LATEST_UNIT_COST??'',price_source:part?.LATEST_PRICE_SOURCE??''};
 }
 function carrierFields(){return <><label>Nhà xe vận chuyển<select aria-label="Nhà xe vận chuyển" value={form.carrier_selection||''} onChange={e=>{const c=refs.carriers?.find(x=>String(x.ID)===e.target.value);V({...form,carrier_selection:e.target.value,...(c?{carrier_name:c.NAME,carrier_phone:c.PHONE,delivery_person:c.NAME}:{})})}}><option value="">Chọn nhà xe đã lưu / nhập trực tiếp</option>{(refs.carriers||[]).map(c=><option key={c.ID} value={c.ID}>{c.CODE} · {c.NAME}</option>)}</select></label>{input('carrier_name','Đơn vị vận chuyển')}{input('carrier_phone','Điện thoại nhà xe')}{input('transport_cost','Cước phải trả nhà xe (VNĐ)','number')}<p className="hint">Chưa biết cước: để trống, bổ sung tại Thu Chi. Nhập 0 nếu công ty không phải trả. Nhà xe được điền vào Người giao hàng; anh có thể sửa riêng.</p><details><summary>Phí vận chuyển khách chịu (tùy chọn)</summary>{input('transport_fee','Phí vận chuyển khách chịu (VNĐ)','number')}<p>Khoản khách thỏa thuận trả công ty; thực nhận tiền ghi phiếu thu riêng.</p></details></>}

