  if(kind==='documents'){route='documents/draft';payload={...form,type:form.type||'IN',supplier_id:form.type==='IN'||form.return_source_id?form.supplier_id||null:null,lines:lines.map(l=>factory&&form.type==='OUT'?{...l,unit_cost:null,sale_unit_price:null}:form.type==='OUT'&&form.sales_purpose!=='SALE'?{...l,unit_cost:''}:l)};}
